void NuRpcService::setExplorerTop100FocusedIndexing(bool enabled)
{
    if (m_explorer_top100_focused_indexing == enabled)
        return;
    m_explorer_top100_focused_indexing = enabled;
    QSettings().setValue(QStringLiteral("ExplorerTop100FocusedIndexing"), enabled);
    const bool priority_changed = trySetProcessNiceForIndexing(enabled);
    if (m_explorer_top100_scanning || m_explorer_indexing) {
        const QString priority_note =
            priority_changed ?
                QStringLiteral(" Process priority adjusted.") :
                (enabled ? QStringLiteral(" Process priority change was not permitted by the OS.") : QString());
        const QString mode_note = enabled ? QStringLiteral("High intensity indexing enabled. Nu will use larger SQLite "
                                                           "batches, bigger cache settings, and fewer UI refreshes.") :
                                            QStringLiteral("High intensity indexing disabled. Nu will return to "
                                                           "cooperative batch sizing and lighter UI cadence.");
        if (m_explorer_top100_scanning) {
            m_explorer_top100_status = mode_note + priority_note;
        }
        if (m_explorer_indexing) {
            m_explorer_index_status = mode_note + priority_note;
        }
        Q_EMIT explorerChanged();
    }
    Q_EMIT settingsChanged();
}

void NuRpcService::setUpnpConnectionsEnabled(bool enabled)
{
    if (m_upnp_connections_enabled == enabled)
        return;
    m_upnp_connections_enabled = enabled;
    QSettings settings;
    settings.setValue(QStringLiteral("UpnpConnectionsEnabled"), enabled);
    Q_EMIT settingsChanged();
    if (!m_rpc_connected)
        return;
    rpcCall(QStringLiteral("setupnpportmapping"),
            {enabled},
            false,
            [this, enabled](const QJsonValue&, const QString& error) {
                if (!error.isEmpty()) {
                    Q_EMIT userMessage(
                        QStringLiteral("Network setting not applied"),
                        QStringLiteral(
                            "The setting was saved, but the running backend did not accept the live UPnP update: %1")
                            .arg(error));
                    return;
                }
                m_upnp_connections_enabled = enabled;
                Q_EMIT settingsChanged();
            });
}

